import unittest
import math
from candidate import greatest_common_divisor

class TestGreatestCommonDivisor(unittest.TestCase):
    def test_gcd_positive_numbers(self):
        self.assertEqual(greatest_common_divisor(48, 18), 6)

    def test_gcd_negative_numbers_both_negative(self):
        self.assertEqual(greatest_common_divisor(-48, -18), -6)

    def test_gcd_one_negative(self):
        self.assertEqual(greatest_common_divisor(-48, 18), 6)
        self.assertEqual(greatest_common_divisor(48, -18), 6)

    def test_gcd_zero_and_nonzero(self):
        self.assertEqual(greatest_common_divisor(0, 5), 5)
        self.assertEqual(greatest_common_divisor(5, 0), 5)

    def test_gcd_zero_and_zero(self):
        self.assertEqual(greatest_common_divisor(0, 0), 0)

    def test_gcd_large_numbers(self):
        a = 123456789012345678901234567890
        b = 987654321098765432109876543210
        expected = math.gcd(a, b)
        self.assertEqual(greatest_common_divisor(a, b), expected)

    def test_gcd_float_inputs(self):
        self.assertEqual(greatest_common_divisor(10.0, 5.0), 5.0)
        self.assertEqual(greatest_common_divisor(7.5, 2.5), 2.5)

    def test_gcd_type_error_with_none(self):
        with self.assertRaises(TypeError):
            greatest_common_divisor(None, 5)

    def test_gcd_type_error_with_string(self):
        with self.assertRaises(TypeError):
            greatest_common_divisor("15", 5)

    def test_gcd_type_error_with_list(self):
        with self.assertRaises(TypeError):
            greatest_common_divisor([15], [5])

    def test_gcd_prime_numbers(self):
        self.assertEqual(greatest_common_divisor(13, 17), 1)

    def test_gcd_common_factor_multiple(self):
        self.assertEqual(greatest_common_divisor(27, 9), 9)

    def test_gcd_identical_numbers(self):
        self.assertEqual(greatest_common_divisor(42, 42), 42)

    def test_gcd_greatest_factor_of_one(self):
        self.assertEqual(greatest_common_divisor(1, 999), 1)
        self.assertEqual(greatest_common_divisor(999, 1), 1)

    def test_gcd_symmetry(self):
        self.assertEqual(greatest_common_divisor(14, 28), greatest_common_divisor(28, 14))

    def test_gcd_negative_a_positive_b(self):
        self.assertEqual(greatest_common_divisor(-14, 28), 14)

    def test_gcd_positive_a_negative_b(self):
        self.assertEqual(greatest_common_divisor(14, -28), 14)

    def test_gcd_type_for_int_input(self):
        result = greatest_common_divisor(21, 7)
        self.assertIsInstance(result, int)

    def test_gcd_type_for_float_input(self):
        result = greatest_common_divisor(12.0, 8.0)
        self.assertIsInstance(result, float)

    def test_gcd_with_large_prime_pair(self):
        a = 10**100 + 7
        b = 10**100 + 19
        self.assertEqual(greatest_common_divisor(a, b), 1)

    def test_gcd_with_negative_large_numbers(self):
        a = -12345678901234567890
        b = -98765432109876543210
        expected = -math.gcd(a, b)
        self.assertEqual(greatest_common_divisor(a, b), expected)

if __name__ == "__main__":
    unittest.main()
